// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { test } from "node:test";

import {
  analyzeProduction,
  controlledSyntheticBenchmark,
  extractPrNumbers,
  receiptCategory,
  renderMarkdown,
  requiredCheckSummary,
  summarizeRuntime,
} from "./evaluate-pr-effectiveness.mjs";

const required = ["build", "test"];
const greenChecks = required.map((name) => ({
  name,
  status: "COMPLETED",
  conclusion: "SUCCESS",
}));

test("missing required check data is never reported green", () => {
  assert.deepEqual(requiredCheckSummary([], required), {
    required,
    required_present: false,
    pending: [],
    failing: [],
    final_head_green: false,
  });
  assert.equal(
    requiredCheckSummary(greenChecks, required).final_head_green,
    true,
  );
  assert.equal(
    requiredCheckSummary([greenChecks[0]], required).final_head_green,
    false,
  );
});

test("task threads accept explicit PR labels and URLs but not bare issue numbers", () => {
  const numbers = extractPrNumbers([
    { body: "Delivered in PR #42" },
    { body: "See https://github.com/monk-eee/MindLeak/pull/43" },
    { body: "Task #44 is not a PR reference" },
  ]);
  assert.deepEqual(
    [...numbers].sort((a, b) => a - b),
    [42, 43],
  );
});

test("production joins branch, task-thread and evidence-commit provenance", () => {
  const pr = {
    number: 42,
    title: "Ship",
    headRefName: "fix/ship",
    headRefOid: "head-sha",
    state: "MERGED",
    mergedAt: "2026-07-30T00:00:00Z",
    commits: [
      {
        oid: "source-sha",
        committedDate: "2026-07-29T00:00:00Z",
        messageHeadline: "change",
      },
      {
        oid: "head-sha",
        committedDate: "2026-07-30T00:00:00Z",
        messageHeadline: "Merge branch 'main' into fix/ship",
      },
    ],
    statusCheckRollup: greenChecks,
  };
  const tasks = [
    { id: "task:branch", branch: "fix/ship", claim_started_at: 1 },
    { id: "task:thread", claim_window: { started_at: 1 } },
    { id: "task:evidence", claim_started_at: 4_000_000_000 },
  ];
  const production = analyzeProduction({
    prs: [pr],
    tasks,
    threadsByTask: { "task:thread": [{ body: "PR #42" }] },
    auditsByTask: {
      "task:branch": [
        {
          checked_at: 1,
          verdict: "aligned",
          evidence: { changed_node_ids: ["artifact:a"] },
        },
      ],
      "task:evidence": [
        {
          checked_at: 2,
          verdict: "needs_human",
          findings: "evidence window is discontinuous",
          evidence: { commit_ids: ["intent:source-sha"] },
        },
      ],
    },
    requiredChecks: required,
  });

  const row = production.pull_requests[0];
  assert.deepEqual(
    row.links.map((link) => [link.task_id, link.methods]),
    [
      ["task:branch", ["branch"]],
      ["task:thread", ["task_thread"]],
      ["task:evidence", ["evidence_commit"]],
    ],
  );
  assert.equal(row.checks.final_head_green, true);
  assert.equal(row.reconciliation_merges, 1);
  assert.equal(row.links[0].claimed_before_first_commit, true);
  assert.equal(row.links[2].claimed_before_first_commit, false);
  assert.deepEqual(row.links[2].finding_causes, ["lease_discontinuity"]);
});

test("state and receipt totals reconcile and incomplete attribution stays visible", () => {
  const base = {
    title: "PR",
    commits: [],
    statusCheckRollup: [],
  };
  const production = analyzeProduction({
    prs: [
      { ...base, number: 1, headRefName: "a", state: "MERGED" },
      { ...base, number: 2, headRefName: "b", state: "OPEN" },
      { ...base, number: 3, headRefName: "c", state: "CLOSED" },
    ],
    tasks: [{ id: "task:a", branch: "a" }],
    auditsByTask: {
      "task:a": [{ verdict: "needs_human", evidence: {}, checked_at: 1 }],
    },
    requiredChecks: required,
  });
  const totals = production.all_available_prs;
  assert.equal(
    totals.merged + totals.open + totals.closed_without_merge,
    totals.prs,
  );
  assert.equal(totals.linked_prs, 1);
  assert.equal(totals.unlinked_prs, 2);
  assert.equal(totals.linked_tasks_with_conformance, 1);
  assert.deepEqual(totals.receipt_categories, { empty_evidence: 1 });
  assert.equal(production.pull_requests[1].attribution_complete, false);
  assert.equal(production.pull_requests[1].checks.final_head_green, false);
});

test("claim timing uses the earliest linked commit, independent of cohort order", () => {
  const task = { id: "task:one", branch: "fix/one", claim_started_at: 150 };
  const production = analyzeProduction({
    prs: [
      {
        number: 2,
        title: "Later PR",
        headRefName: "fix/one",
        state: "MERGED",
        commits: [
          {
            oid: "later",
            committedDate: "1970-01-01T00:03:20Z",
            messageHeadline: "later",
          },
        ],
      },
      {
        number: 1,
        title: "Earlier PR",
        headRefName: "fix/one",
        state: "MERGED",
        commits: [
          {
            oid: "earlier",
            committedDate: "1970-01-01T00:01:40Z",
            messageHeadline: "earlier",
          },
        ],
      },
    ],
    tasks: [task],
  });

  assert.deepEqual(production.all_available_prs.claim_before_first_commit, {
    before: 0,
    after: 1,
    unknown: 0,
    rate: 0,
  });
});

test("receipt category distinguishes absent and empty conformance", () => {
  assert.equal(receiptCategory([]), "no_conformance");
  assert.equal(
    receiptCategory([{ verdict: "aligned", evidence: {} }]),
    "empty_evidence",
  );
  assert.equal(
    receiptCategory([
      { verdict: "aligned", evidence: '{"commit_ids":["intent:abc"]}' },
    ]),
    "aligned",
  );
});

test("runtime summary separates lifetime history, polling, latency and habits", () => {
  const runtime = summarizeRuntime({
    total_events: 100,
    total_errors: 5,
    currently_failing_tools: 1,
    by_name: [
      { name: "graph_stats", calls: 20 },
      { name: "telemetry_snapshot", calls: 10 },
      { name: "recall", calls: 70 },
    ],
    recent: [
      { ts: 1, name: "recall", outcome: "ok", duration_ms: 4 },
      {
        ts: 2,
        name: "recall",
        outcome: "error",
        duration_ms: 8,
        detail: { cause: "x" },
      },
    ],
    memory_habits: [
      { agent_id: "a", read_before_first_write: true },
      { agent_id: "b", read_before_first_write: false },
      { agent_id: "c", read_before_first_write: null },
    ],
  });
  assert.equal(runtime.lifetime_error_rate, 0.05);
  assert.equal(runtime.polling_share, 0.3);
  assert.equal(runtime.recent_latency_ms.average, 6);
  assert.equal(runtime.recent_errors.length, 1);
  assert.deepEqual(runtime.recent_errors[0], {
    ts: 2,
    name: "recall",
    category: null,
  });
  assert.equal(runtime.memory_read_before_write.adoption_rate, 0.5);
});

test("controlled fixture passes and markdown keeps evidence tiers separate", () => {
  const controlled = controlledSyntheticBenchmark();
  assert.equal(controlled.passed, controlled.total);
  const markdown = renderMarkdown({
    generated_at: "2026-07-30T00:00:00Z",
    runtime: summarizeRuntime({}),
    production: analyzeProduction({}),
    controlled_synthetic: controlled,
    limitations: ["MindLeak tool events do not carry PR ids."],
  });
  assert.match(markdown, /Runtime health/);
  assert.match(markdown, /Production correlation/);
  assert.match(markdown, /Controlled synthetic/);
  assert.match(markdown, /do not carry PR ids/);
});
